\begin{prop}\ollabel{prop:provability-exhaustive}
  If $\Gamma \cup \{!A\}$ and $\Gamma \cup \{\lnot !A\}$ are both
  inconsistent, then $\Gamma$ is inconsistent.
\end{prop}

